import React, { useEffect, useState } from 'react';
import { Link } from 'react-router-dom';
import { useLang } from '../LangContext';
import AdBanner from '../components/AdBanner';
import { SocialIcons } from '../components/socials';

export default function Home() {
  const { t } = useLang();
  return (
    <>
      <div className="page">
      {/* Hero */}
      <section style={{ padding: '60px 0 50px', textAlign: 'center' }}>
        <div style={{ display: 'inline-flex', alignItems: 'center', gap: 8, background: '#22c55e15', border: '1px solid #22c55e40', borderRadius: 50, padding: '6px 16px', marginBottom: 24 }}>
          <span style={{ color: '#22c55e', fontSize: 13 }}>✓ {t.heroTag}</span>
        </div>
        <h1 style={{ fontSize: 'clamp(28px, 5vw, 64px)', fontWeight: 900, lineHeight: 1.15, marginBottom: 20 }}>
          {t.heroTitle1}<br /><span style={{ color: '#f97316' }}>{t.heroTitle2}</span>
        </h1>
        <p style={{ fontSize: 'clamp(14px, 2vw, 18px)', color: '#a3a3a3', maxWidth: 520, margin: '0 auto 32px', lineHeight: 1.7 }}>
          {t.heroDesc}
        </p>

        {/* Phone-sized Ad */}
        <PhoneAd />

        <div style={{ display: 'flex', gap: 12, justifyContent: 'center', flexWrap: 'wrap', marginTop: 32 }}>
          <Link to="/contact" style={{ padding: '13px 28px', background: '#f97316', color: '#000', borderRadius: 10, fontWeight: 700, fontSize: 15 }}>{t.applyNow}</Link>
          <Link to="/clients" style={{ padding: '13px 28px', background: '#171717', color: '#fff', borderRadius: 10, fontWeight: 600, fontSize: 15, border: '1px solid #333' }}>{t.viewClients}</Link>
        </div>
        <div style={{ display: 'flex', justifyContent: 'center', marginTop: 24 }}>
          <SocialIcons size={40} iconSize={20} />
        </div>
      </section>

      {/* Stats */}
      <section className="grid-3" style={{ marginBottom: 60 }}>
        {[['50+', t.totalClients], ['100%', t.licensed], ['200%', t.avgGrowth]].map(([v, l]) => (
          <div key={l} style={{ background: '#171717', border: '1px solid #262626', borderRadius: 20, padding: '28px 20px', textAlign: 'center' }}>
            <div style={{ fontSize: 'clamp(28px, 4vw, 42px)', fontWeight: 900, color: '#f97316' }}>{v}</div>
            <div style={{ color: '#a3a3a3', marginTop: 6, fontSize: 14 }}>{l}</div>
          </div>
        ))}
      </section>

      {/* Services */}
      <section style={{ marginBottom: 60 }}>
        <h2 style={{ fontSize: 'clamp(22px, 3vw, 32px)', fontWeight: 800, marginBottom: 28, textAlign: 'center' }}>{t.ourServices}</h2>
        <div className="grid-2">
          {[
            ['📱', t.service1Title, t.service1Desc],
            ['🎨', t.service2Title, t.service2Desc],
            ['📈', t.service3Title, t.service3Desc],
            ['💰', t.service4Title, t.service4Desc],
          ].map(([icon, title, desc]) => (
            <div key={title} style={{ background: '#171717', border: '1px solid #262626', borderRadius: 16, padding: '20px 22px', display: 'flex', gap: 16, alignItems: 'flex-start' }}>
              <span style={{ fontSize: 28, flexShrink: 0 }}>{icon}</span>
              <div>
                <h3 style={{ fontSize: 16, fontWeight: 700, marginBottom: 6 }}>{title}</h3>
                <p style={{ color: '#a3a3a3', fontSize: 14, lineHeight: 1.6 }}>{desc}</p>
              </div>
            </div>
          ))}
        </div>
      </section>
    </div>
    </>
  );
}

function PhoneAd() {
  const [ads, setAds] = useState([]);
  const [index, setIndex] = useState(0);

  useEffect(() => {
    fetch('http://localhost:5000/api/ads/active')
      .then(r => r.json())
      .then(data => { if (Array.isArray(data) && data.length) setAds(data); })
      .catch(() => {});
  }, []);

  useEffect(() => {
    if (ads.length <= 1) return;
    const t = setInterval(() => setIndex(i => (i + 1) % ads.length), 4000);
    return () => clearInterval(t);
  }, [ads]);

  if (!ads.length) return null;
  const ad = ads[index];

  return (
    <div style={{ width: '100%', marginTop: 40, position: 'relative', borderRadius: 20, overflow: 'hidden', boxShadow: '0 20px 60px rgba(0,0,0,0.5)' }}>
      {/* ad image */}
      {ad.image_url && (
        <img src={ad.image_url} alt={ad.title} style={{ width: '100%', height: 480, objectFit: 'cover', display: 'block' }} />
      )}
      {/* overlay */}
      <div style={{ position: 'absolute', inset: 0, background: 'linear-gradient(to top, rgba(0,0,0,0.85) 0%, transparent 50%)', display: 'flex', flexDirection: 'column', justifyContent: 'flex-end', padding: '32px 36px' }}>
        {ad.title && <div style={{ fontWeight: 800, fontSize: 28, color: '#fff', marginBottom: 8 }}>{ad.title}</div>}
        {ad.description && <div style={{ color: '#ddd', fontSize: 15, marginBottom: 20, lineHeight: 1.6, maxWidth: 600 }}>{ad.description}</div>}
        {ad.link_url ? (
          <a href={ad.link_url} target="_blank" rel="noopener noreferrer" style={viewMoreBtn}>View More →</a>
        ) : (
          <span style={viewMoreBtn}>View More →</span>
        )}
      </div>
      {/* dots */}
      {ads.length > 1 && (
        <div style={{ position: 'absolute', bottom: 16, right: 24, display: 'flex', gap: 6, alignItems: 'center' }}>
          {ads.map((_, i) => (
            <div key={i} onClick={() => setIndex(i)} style={{
              width: i === index ? 22 : 8, height: 8, borderRadius: 4,
              background: i === index ? '#f97316' : 'rgba(255,255,255,0.4)',
              cursor: 'pointer', transition: 'width 0.3s',
            }} />
          ))}
        </div>
      )}
    </div>
  );
}

const viewMoreBtn = {
  display: 'inline-block', padding: '8px 20px',
  background: '#f97316', color: '#000',
  borderRadius: 20, fontWeight: 700, fontSize: 13,
  textDecoration: 'none', cursor: 'pointer',
};
